// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.addToBalance{value: 1 wei}();
        vm.prank(alice);
        c.withdrawBalance();
        uint256 bal = c.getBalance(alice);
        assertTrue(bal == 0, "After withdrawal, balance should be zero");
    }
}
